import { after } from 'next/after'

async function logPageView() {
  // Replace with your actual analytics call (e.g. Segment, Amplitude, etc.)
  await fetch('https://analytics.example.com/track', {
    method: 'POST',
    body: JSON.stringify({ event: 'page_view', path: '/' }),
  })
}

export default function Home() {
  after(() => logPageView())

  return (
    <main>
      <h1>Welcome</h1>
      <p>Your page view has been logged (after the response was sent).</p>
    </main>
  )
}

